  </style>
</head>
<body>
  <header class="masthead shell">
    <div class="wordmark">FIELD NOTES</div>
    <nav aria-label="Main navigation">
      <a href="#work">Work</a>
      <a href="#about">About</a>
      <a href="mailto:studio@example.test">Contact</a>
    </nav>
  </header>
  <main class="shell">
    <section class="hero" aria-labelledby="hero-title">
      <h1 id="hero-title"><span>Make room for</span> <span>the moving world.</span></h1>
      <div class="hero-detail">
        <p>Thoughtful films, clear stories, lasting places.</p>
        <a class="primary" href="#work">Explore the work<svg class="arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M4 12h15M13 5l7 7-7 7"/></svg></a>
      </div>
      <div class="media" data-media>
        <img src="assets/poster.svg" alt="" width="960" height="540" fetchpriority="high">
        <video src="assets/scene.webm" poster="assets/poster.svg" muted playsinline loop preload="none" aria-hidden="true" hidden></video>
        <button class="media-control" type="button" aria-label="Play background video" data-playing="false" hidden>
          <svg class="pause-icon" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true"><path d="M5 3h3v14H5zM12 3h3v14h-3z"/></svg>
          <svg class="play-icon" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true"><path d="m6 3 11 7-11 7z"/></svg>
        </button>
        <span class="sr-only" data-media-status role="status"></span>
      </div>
    </section>
    <section id="work" aria-labelledby="work-title">
      <h2 id="work-title">Selected work</h2>
      <ul class="work-list">
        <li>Tidal study <span class="year">/ 2026</span></li>
        <li>Mountain light <span class="year">/ 2025</span></li>
      </ul>
    </section>
    <section id="about" aria-label="About">
      <p>An independent film practice.</p>
    </section>
  </main>
  <script>
    (() => {
      const root = document.querySelector('"'[data-media]');
      const video = root.querySelector('video');
      const button = root.querySelector('button');
      const status = root.querySelector('[data-media-status]');
      let teardown = () => {};
      function mount() {
        let observer;
        let epoch = 0;
        let dead = false;
        let visible = false;
        let userPaused = false;
        let blocked = false;
        const listeners = [];
        const listen = (target, event, handler) => {
          target.addEventListener(event, handler);
          listeners.push(() => target.removeEventListener(event, handler));
        };
        const still = () => {
          epoch++;
          video.pause();
          video.hidden = true;
          button.dataset.playing = 'false';
          button.setAttribute('aria-label', 'Play background video');
        };
        let reduce;
        const sync = async () => {
          if (dead || "'!visible || userPaused || blocked || reduce.matches || document.hidden) {
            still();
            return;
          }
          const attempt = ++epoch;
          try {
            await video.play();
            if (attempt !== epoch || dead) return;
            video.hidden = false;
            button.dataset.playing = '"'true';
            button.setAttribute('aria-label', 'Pause background video');
            status.textContent = '';
          } catch {
            if (attempt "'!== epoch || dead) return;
            blocked = true;
            still();
            status.textContent = '"'Static preview: playback unavailable.';
          }
        };
        try {
          reduce = window.matchMedia('(prefers-reduced-motion: reduce)');
          if ("'!('"'IntersectionObserver' in window)) return;
          video.muted = true;
          listen(button, 'click', () => {
            userPaused = "'!video.paused;
            blocked = false;
            sync();
          });
          listen(reduce, '"'change', sync);
          listen(document, 'visibilitychange', sync);
          listen(video, 'error', () => {
            blocked = true;
            still();
            status.textContent = 'Static preview: media unavailable.';
          });
          observer = new IntersectionObserver(([entry]) => {
            visible = entry.isIntersecting && entry.intersectionRatio > 0;
            sync();
          }, { threshold: [0, .001] });
          observer.observe(root);
          button.hidden = false;
        } catch {
          blocked = true;
          still();
          button.hidden = true;
        }
        teardown = () => {
          dead = true;
          still();
          observer?.disconnect();
          listeners.forEach(remove => remove());
          button.hidden = true;
        };
      }
      mount();
      window.addEventListener('pagehide', () => teardown());
      window.addEventListener('pageshow', event => { if (event.persisted) mount(); });
    })();
  </script>
</body>
</html>
